-- 568: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 15 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_568_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_568_guard;
INSERT INTO _migration_568_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_057' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_emp' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Unemployment is best defined as the situation in which...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. People who are willing and able to work cannot find jobs","B. Workers go on strike for higher pay","C. People retire from active service","D. Students attend school on a full-time basis"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The unemployed are members of the labour force who are willing, able and actively seeking work but cannot find it. Striking workers already have jobs, and retirees and full-time students are not in the labour force at all, so none of them counts as unemployed. Therefore the correct answer is A: People who are willing and able to work cannot find jobs.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_057' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_568_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_058' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_emp' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A farmer who is idle during the dry season, when no planting or harvesting takes place, experiences...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Structural unemployment","B. Seasonal unemployment","C. Frictional unemployment","D. Cyclical unemployment"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Seasonal unemployment follows the calendar: farmhands, fishing crews and construction workers lose work in off-seasons. Structural unemployment comes from a mismatch of skills, frictional unemployment is the short gap while moving between jobs, and cyclical unemployment follows downturns in the business cycle. Therefore the correct answer is B: Seasonal unemployment.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_058' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_568_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_059' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_emp' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A person who identifies a business opportunity, organizes resources and bears the risk of starting an enterprise is called...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A civil servant","B. A shareholder","C. An entrepreneur","D. A middleman"]' AND q.correct_answer IS 'C' AND q.explanation IS 'An entrepreneur combines land, labour and capital, takes the risk of failure and earns profit if the venture succeeds. A civil servant is a salaried state employee, a shareholder merely owns part of a company, and a middleman only links producers to buyers without organizing production. Therefore the correct answer is C: An entrepreneur.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_059' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_568_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_060' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_emp' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following workers operates in Ghana’s informal sector?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A teacher employed by the Ghana Education Service","B. A bank manager in a commercial bank","C. An engineer at a licensed mining company","D. A self-employed market trader whose business is not registered"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The informal sector covers unregistered, unregulated, mostly small-scale work — market trading, street vending, artisan work — without formal contracts or social security. Teaching in public schools, banking and licensed mining are formal-sector jobs with registered employers and regulated conditions. Therefore the correct answer is D: A self-employed market trader whose business is not registered.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_060' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_057', 'topic_wassce_p2_soc_emp', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Unemployment is best defined as the situation in which...', 'multiple_choice', NULL, '["A. People who are willing and able to work cannot find jobs","B. Workers go on strike for higher pay","C. People retire from active service","D. Students attend school on a full-time basis"]', 'A', 'The unemployed are members of the labour force who are willing, able and actively seeking work but cannot find it. Striking workers already have jobs, and retirees and full-time students are not in the labour force at all, so none of them counts as unemployed. Therefore the correct answer is A: People who are willing and able to work cannot find jobs.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec');
